CREATE DATABASE IF NOT EXISTS ops_ticket CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci;
USE ops_ticket;
CREATE TABLE IF NOT EXISTS ticket (id BIGINT NOT NULL AUTO_INCREMENT,ticket_no VARCHAR(32) NOT NULL,title VARCHAR(128) NOT NULL,description TEXT NOT NULL,priority VARCHAR(16) NOT NULL,status VARCHAR(32) NOT NULL,creator_id BIGINT NOT NULL,assignee_id BIGINT,version INT NOT NULL DEFAULT 0,create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,update_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,deleted TINYINT NOT NULL DEFAULT 0,PRIMARY KEY(id),UNIQUE KEY uk_ticket_no(ticket_no),KEY idx_ticket_creator_time(creator_id,create_time),KEY idx_ticket_assignee_status_time(assignee_id,status,update_time)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS ticket_comment (id BIGINT NOT NULL AUTO_INCREMENT,ticket_id BIGINT NOT NULL,user_id BIGINT NOT NULL,content VARCHAR(2000) NOT NULL,create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,update_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,deleted TINYINT NOT NULL DEFAULT 0,PRIMARY KEY(id),KEY idx_comment_ticket_time(ticket_id,create_time)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS ticket_attachment (id BIGINT NOT NULL AUTO_INCREMENT,ticket_id BIGINT NOT NULL,file_name VARCHAR(255) NOT NULL,storage_path VARCHAR(512) NOT NULL,file_size BIGINT NOT NULL,content_type VARCHAR(128),create_by BIGINT NOT NULL,create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,deleted TINYINT NOT NULL DEFAULT 0,PRIMARY KEY(id),KEY idx_attachment_ticket(ticket_id,create_time)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS ticket_history (id BIGINT NOT NULL AUTO_INCREMENT,ticket_id BIGINT NOT NULL,operator_id BIGINT NOT NULL,operation_type VARCHAR(32) NOT NULL,from_status VARCHAR(32),to_status VARCHAR(32) NOT NULL,remark VARCHAR(512),create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(id),KEY idx_history_ticket_time(ticket_id,create_time)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS ticket_assignment (id BIGINT NOT NULL AUTO_INCREMENT,ticket_id BIGINT NOT NULL,assignee_id BIGINT NOT NULL,assigned_by BIGINT NOT NULL,assignment_type VARCHAR(32) NOT NULL,create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(id),KEY idx_assignment_ticket_time(ticket_id,create_time),KEY idx_assignment_assignee_time(assignee_id,create_time)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS ticket_operation_log (id BIGINT NOT NULL AUTO_INCREMENT,ticket_id BIGINT NOT NULL,operator_id BIGINT NOT NULL,operation VARCHAR(64) NOT NULL,request_id VARCHAR(64),detail_json JSON,create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(id),KEY idx_operation_ticket_time(ticket_id,create_time),KEY idx_operation_request(request_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
